## 5. Modern Verification with `Swift Testing` (`import Testing`)

- **WHY**: Legacy `XCTest` relies on reference-type `XCTestCase` subclasses (which share mutable properties across tests if not reset), verbose `XCTAssertEqual` macros, and fragile `XCTestExpectation` timers.
- **DO** write all new unit and integration tests using `import Testing` with value-type `@Suite struct` (providing fresh instance isolation per test), `#expect(...)`, `try #require(...)`, parameterized `@Test(arguments:)`, and `await confirmation(...)`:

```swift
import Testing
@testable import CoreEngine

@Suite("RateLimiter Token Bucket Policy")
struct RateLimiterTests {
    @Test("Allows bursts up to capacity and rejects excess", arguments: [1, 3, 5])
    func burstCapacity(capacity: Int) throws {
        let limiter = RateLimiter(maxTokens: capacity)

        for _ in 0..<capacity {
            #expect(throws: Never.self) {
                try limiter.tryAcquire(cost: 1)
            }
        }

        #expect(throws: RateLimitError.exhausted(available: 0)) {
            try limiter.tryAcquire(cost: 1)
        }
    }

    @Test("Unwraps required state and confirms async event emission")
    func eventStreamDelivery() async throws {
        let rawConfig: [String: String] = ["endpoint": "https://api.example.com"]
        let endpoint = try #require(rawConfig["endpoint"])
        #expect(endpoint.hasPrefix("https://"))

        await confirmation("Receives exactly 1 heartbeat", expectedCount: 1) { confirm in
            confirm()
        }
    }
}
```

