## 3. Menu Bar, Responder Chain & Keyboard-First Ergonomics

A native Mac app must be operable without touching the mouse. Every primary action must live in the global macOS Menu Bar (`Commands`) and wire into the active window via Focus values.

- **DO** publish window-scoped state to the menu bar using `@Entry` in `FocusedValues` and `@FocusedValue` / `@FocusedBinding`:

```swift
import SwiftUI

// 1. Define strongly-typed focus keys via @Entry
extension FocusedValues {
    @Entry var activeDocument: DocumentViewModel?
    @Entry var isFilterSidebarVisible: Binding<Bool>?
}

// 2. Attach to the active scene/view hierarchy
struct WorkspaceView: View {
    @Bindable var viewModel: DocumentViewModel
    @State private var showFilter = true

    var body: some View {
        NavigationSplitView {
            SidebarView()
        } detail: {
            EditorCanvasView(viewModel: viewModel)
        }
        .focusedSceneValue(\.activeDocument, viewModel)
        .focusedSceneValue(\.isFilterSidebarVisible, $showFilter)
    }
}

// 3. Consume in Menu Bar Commands with proper .disabled() guards
struct DocumentCommands: Commands {
    @FocusedValue(\.activeDocument) private var document
    @FocusedBinding(\.isFilterSidebarVisible) private var isFilterVisible

    var body: some Commands {
        CommandGroup(after: .newItem) {
            Button("Export Snapshot...") {
                document?.exportSnapshot()
            }
            .keyboardShortcut("e", modifiers: [.command, .shift])
            .disabled(document == nil)
        }
        CommandMenu("View Options") {
            Toggle("Show Filter Inspector", isOn: Binding(
                get: { isFilterVisible ?? false },
                set: { isFilterVisible = $0 }
            ))
            .keyboardShortcut("f", modifiers: [.command, .option])
            .disabled(isFilterVisible == nil)
        }
    }
}
```

