## 5. File System, Sandboxing & Security-Scoped Bookmarks

In sandboxed macOS apps (`com.apple.security.app-sandbox = true`), a `URL` returned by `NSOpenPanel` or `.fileImporter` loses access permission as soon as the process exits.

- **DO** persist external folder/file access across launches using **Security-Scoped Bookmarks** and always pair `startAccessingSecurityScopedResource()` with `defer { url.stopAccessingSecurityScopedResource() }`:

```swift
import Foundation

enum SandboxBookmarkStore {
    static func saveBookmark(for url: URL) throws -> Data {
        try url.bookmarkData(
            options: [.withSecurityScope],
            includingResourceValuesForKeys: nil,
            relativeTo: nil
        )
    }

    static func withScopedAccess<T>(
        bookmarkData: Data,
        refreshStore: (Data) -> Void,
        operation: (URL) throws -> T
    ) throws -> T {
        var isStale = false
        let resolvedURL = try URL(
            resolvingBookmarkData: bookmarkData,
            options: [.withSecurityScope],
            relativeTo: nil,
            bookmarkDataIsStale: &isStale
        )
        guard resolvedURL.startAccessingSecurityScopedResource() else {
            throw CocoaError(.fileReadNoPermission)
        }
        defer { resolvedURL.stopAccessingSecurityScopedResource() }

        if isStale {
            let freshData = try saveBookmark(for: resolvedURL)
            refreshStore(freshData)
        }
        return try operation(resolvedURL)
    }
}
```

